# IR verifier: checked numeric arithmetic, direct relations and legal explicit conversions.
replace_once(
    "bootstrap/s3/verifier.py",
    '''        if opcode in {IROpcode.ADD, IROpcode.MINIMUM, IROpcode.MAXIMUM}:\n            _, result_type = require_result()\n            operand_types = require_operands(2)\n            self._require_same_types(\n                (result_type, *operand_types),\n                opcode.value,\n                instruction.location,\n            )\n            if result_type is IRType.STRING:\n                self._error(\n                    f"{opcode.value} does not support string values",\n                    instruction.location,\n                )\n            if result_type is IRType.REFERENCE:\n                self._error(f"{opcode.value} does not support reference values", instruction.location)\n            if result_type in {IRType.I64, IRType.F64} and opcode is not IROpcode.ADD:\n                self._error(f"{opcode.value} does not support numeric values", instruction.location)\n            return\n\n        if opcode is IROpcode.COMPARE:\n''',
    '''        if opcode in {\n            IROpcode.ADD,\n            IROpcode.MULTIPLY,\n            IROpcode.DIVIDE,\n            IROpcode.MINIMUM,\n            IROpcode.MAXIMUM,\n        }:\n            _, result_type = require_result()\n            operand_types = require_operands(2)\n            self._require_same_types(\n                (result_type, *operand_types),\n                opcode.value,\n                instruction.location,\n            )\n            if result_type in {IRType.STRING, IRType.REFERENCE}:\n                self._error(\n                    f"{opcode.value} does not support {result_type.value} values",\n                    instruction.location,\n                )\n            if (\n                opcode in {IROpcode.MULTIPLY, IROpcode.DIVIDE}\n                and result_type not in {IRType.I64, IRType.F64}\n            ):\n                self._error(f"{opcode.value} requires i64 or f64 values", instruction.location)\n            if (\n                opcode in {IROpcode.MINIMUM, IROpcode.MAXIMUM}\n                and result_type in {IRType.I64, IRType.F64}\n            ):\n                self._error(f"{opcode.value} is balanced-ternary only", instruction.location)\n            return\n\n        if opcode is IROpcode.RELATE:\n            _, result_type = require_result()\n            operand_types = require_operands(2)\n            if result_type is not IRType.TRIT:\n                self._error("relate result must have type trit", instruction.location)\n            self._require_same_types(operand_types, "relate operands", instruction.location)\n            if not operand_types or operand_types[0] not in {\n                IRType.TRIT, IRType.TRYTE, IRType.I64, IRType.F64\n            }:\n                self._error("relate requires scalar numeric operands", instruction.location)\n            if not isinstance(instruction.immediate, int) or instruction.immediate not in range(6):\n                self._error("relate requires relation code 0..5", instruction.location)\n            return\n\n        if opcode is IROpcode.CONVERT:\n            _, result_type = require_result()\n            operand_types = require_operands(1)\n            source_type = operand_types[0]\n            allowed = {\n                (IRType.TRIT, IRType.I64),\n                (IRType.TRYTE, IRType.I64),\n                (IRType.TRIT, IRType.F64),\n                (IRType.TRYTE, IRType.F64),\n                (IRType.I64, IRType.F64),\n                (IRType.I64, IRType.TRYTE),\n            }\n            if (source_type, result_type) not in allowed:\n                self._error(\n                    f"unsupported explicit conversion {source_type.value} -> {result_type.value}",\n                    instruction.location,\n                )\n            return\n\n        if opcode is IROpcode.COMPARE:\n''',
)

# IR emulator: mirror checked i64 and IEEE-754 semantics.
replace_once(
    "bootstrap/s3/ir_emulator.py",
    "from .numeric import NumericType, validate_f64, validate_i64\n",
    "from .numeric import (\n    NumericError, NumericValue, checked_i64_add, checked_i64_mul,\n    checked_i64_div, checked_i64_neg, checked_i64_to_tryte,\n    validate_f64, validate_i64,\n)\n",
)
replace_once(
    "bootstrap/s3/ir_emulator.py",
    '''        elif op is IROpcode.INVERT:\n            _write(frame, instruction.result, invert(_read(frame, instruction.operands[0]), _width(_register_type(function, instruction.result))))\n        elif op is IROpcode.ADD:\n            result_type = _register_type(function, instruction.result)\n            if result_type is IRType.I64:\n                _write(frame, instruction.result, validate_i64(_read(frame, instruction.operands[0]) + _read(frame, instruction.operands[1])))\n            elif result_type is IRType.F64:\n                _write(frame, instruction.result, validate_f64(_read(frame, instruction.operands[0]) + _read(frame, instruction.operands[1])))\n            else:\n                _write(frame, instruction.result, add(_read(frame, instruction.operands[0]), _read(frame, instruction.operands[1]), _width(result_type)))\n        elif op in {IROpcode.MINIMUM, IROpcode.MAXIMUM}:\n''',
    '''        elif op is IROpcode.INVERT:\n            result_type = _register_type(function, instruction.result)\n            value = _read(frame, instruction.operands[0])\n            if result_type is IRType.I64:\n                result = checked_i64_neg(value)\n            elif result_type is IRType.F64:\n                result = validate_f64(-float(value))\n            else:\n                result = invert(value, _width(result_type))\n            _write(frame, instruction.result, result)\n        elif op in {IROpcode.ADD, IROpcode.MULTIPLY, IROpcode.DIVIDE}:\n            result_type = _register_type(function, instruction.result)\n            left = _read(frame, instruction.operands[0])\n            right = _read(frame, instruction.operands[1])\n            if result_type is IRType.I64:\n                if op is IROpcode.ADD:\n                    result = checked_i64_add(left, right)\n                elif op is IROpcode.MULTIPLY:\n                    result = checked_i64_mul(left, right)\n                else:\n                    result = checked_i64_div(left, right)\n            elif result_type is IRType.F64:\n                if op is IROpcode.ADD:\n                    result = validate_f64(float(left) + float(right))\n                elif op is IROpcode.MULTIPLY:\n                    result = validate_f64(float(left) * float(right))\n                else:\n                    result = NumericValue.f64(float(left)).divide(NumericValue.f64(float(right))).value\n            else:\n                result = add(left, right, _width(result_type))\n            _write(frame, instruction.result, result)\n        elif op is IROpcode.RELATE:\n            left = _read(frame, instruction.operands[0])\n            right = _read(frame, instruction.operands[1])\n            relation = instruction.immediate\n            truth = {\n                0: left == right,\n                1: left != right,\n                2: left < right,\n                3: left <= right,\n                4: left > right,\n                5: left >= right,\n            }[relation]\n            _write(frame, instruction.result, -1 if truth else 0)\n        elif op is IROpcode.CONVERT:\n            source_type = _register_type(function, instruction.operands[0])\n            result_type = _register_type(function, instruction.result)\n            value = _read(frame, instruction.operands[0])\n            if result_type is IRType.I64:\n                result = validate_i64(int(value))\n            elif result_type is IRType.F64:\n                result = validate_f64(value)\n            elif source_type is IRType.I64 and result_type is IRType.TRYTE:\n                result = checked_i64_to_tryte(value)\n            else:\n                raise IRExecutionError(f"unsupported conversion {source_type.value} -> {result_type.value}")\n            _write(frame, instruction.result, result)\n        elif op in {IROpcode.MINIMUM, IROpcode.MAXIMUM}:\n''',
)

